-- Generated by scripts/gen-civic-sql.mjs from data/civic/*.json. Do not edit by hand.
-- 70 documented challenges (open interpellations) and 41 tracked projects (promises),
-- published by the editorial account @politique. Safe to re-run: existing rows are left as they are.
set search_path = politique, extensions, public;
do $$ begin
  if not exists (select 1 from politique.profiles where handle = 'politique') then
    raise exception 'editorial account @politique is missing: run supabase/seed/editorial_account.sql first';
  end if;
end $$;

insert into posts (id, author_id, kind, text, lang, commune_id, created_at)
select v.post::uuid, ed.id, 'post', v.text, 'fr', o.commune_id, now() - make_interval(secs => v.n)
from (values
('bb7b6cfb-d83e-89d1-8be5-d00236e00b95', 'maire-bouake', 'Budget 2024 : seulement 17 % des investissements exécutés. Comment faire mieux ?

Le budget 2024 de Bouaké (8,42 milliards de FCFA) a été exécuté à 59,59 % : 82,46 % pour le fonctionnement, mais 17 % seulement pour l''investissement. Le conseil municipal a lui-même demandé de mieux mobiliser les ressources pour éviter les sous-exécutions. Quelles mesures pour que les projets votés se réalisent ?

Ivoireinfos, 16 mars 2025 : https://ivoireinfos.com/2025/03/16/bouake-le-premier-conseil-municipal-de-2025-adopte-plusieurs-projets-structurants/
#Interpellation #Bouaké', 24),
('11b74392-9166-fd6a-a293-caa4bffbbd89', 'maire-abobo', 'Logement : comment loger décemment une population qui ne cesse de croître ?

Le besoin de logements décents à Abobo est jugé assez important pour justifier un programme de 5 000 logements sociaux, économiques et de standing, en location-vente sur 25 ans. Quels critères d''attribution, et quel calendrier pour les premiers ménages ?

Fraternité Matin, 27 janvier 2026 : https://www.fratmat.info/article/2639616/economie/construction-5000-logements-sociaux-economiques-sortiront-de-terre-a-abobo-dici-5-ans
#Interpellation #Abobo', 23),
('1787e984-f8f7-075e-cc66-5c5ff03745ee', 'maire-adjame', 'Carrefour Liberté, gare Nord : comment tenir durablement la salubrité ?

Une opération de nettoyage du 1er novembre 2024 a démantelé des étals et retiré des gravats au carrefour Liberté et à la gare Nord. Ces opérations reviennent régulièrement : quel dispositif pour que l''espace public reste dégagé et propre ?

Le Patriote, 5 novembre 2024 : https://lepatriote.ci/adjame-lutte-contre-linsalubrite-liberte-et-la-gare-nord-nettoyes/
#Interpellation #Adjamé', 22),
('fa22b57c-b174-2ab1-b3b6-9926413ea051', 'maire-attecoube', 'Gbebouto et Espoir : talus instables et assainissement, qui sera indemnisé et quand ?

Les quartiers Gbebouto et Espoir sont directement touchés par le Projet d''assainissement et de résilience urbaine (PARU) : assainissement, stabilisation des talus, libération des emprises. La mairie a annoncé des comités de plaintes, d''écoute et d''indemnisation. Comment les familles concernées seront-elles accompagnées ?

Mairie d''Attécoubé, 14 avril 2026 : https://mairieattecoube.ci/actualite_details/106
#Interpellation #Attécoubé', 21),
('38868ade-be67-3514-de10-482a1f39d8fa', 'maire-cocody', 'Inondations : quels travaux sur les points critiques avant la prochaine saison des pluies ?

Les pluies de juin 2025 ont coupé des voies, inondé des bâtiments et piégé des véhicules. Cocody connaît ce type de crise chaque année et des travaux d''envergure sont nécessaires sur les points critiques. Quel calendrier ?

Abidjan.net, 16 juin 2025 : https://news.abidjan.net/articles/742426/inondations-a-cocody-le-conseil-municipal-aux-cotes-des-populations-sinistrees
#Interpellation #Cocody #Inondations', 20),
('30570447-b6cf-df36-342a-fa9fecb690f9', 'maire-cocody', 'Mobilité : comment fluidifier la circulation dans la commune ?

La mairie identifie elle-même la mobilité urbaine comme un défi et cherche des partenariats pour améliorer les déplacements et les livraisons. Quelles mesures concrètes sont prévues ?

AIP, via Abidjan.net, 19 mars 2024 : https://news.abidjan.net/articles/729718/le-maire-de-cocody-veut-relever-les-defis-de-la-mobilite-dans-sa-commune
#Interpellation #Cocody', 19),
('7ef08594-bd1a-f57a-4e9d-8981243fa3cf', 'maire-koumassi', 'Camp commando, gare Sito, quartier Divo : quel plan contre les inondations ?

L''ONPC a inspecté le 17 juillet 2024 plusieurs points de Koumassi sensibles aux pluies diluviennes : abords du camp commando, arrière de la gare Sito, rue des Sciences et plusieurs sites du quartier Divo. Quels aménagements pour protéger les riverains ?

Office national de la protection civile, 17 juillet 2024 : https://onpc-ci.org/actualite/sites-sensibles-aux-inondations-les-points-critiques-de-la-commune-de-koumassi-visites
#Interpellation #Koumassi #Inondations', 18),
('388510c6-3503-215a-bd43-b3f16af17fc3', 'maire-marcory', 'Trottoirs occupés, salubrité : qu''attendre des États généraux annoncés ?

Le maire a fixé comme priorités la libération des trottoirs, l''assainissement et une meilleure organisation de l''espace public, et annoncé des États généraux de la qualité et de la salubrité. Quand auront-ils lieu, et avec quels engagements ?

CI News, 14 février 2026 : https://cinews.ci/marcory-le-maire-raoul-aby-annonce-lorganisation-des-etats-generaux-de-la-qualite-et-de-la-salubrite/
#Interpellation #Marcory', 17),
('7060224a-66a5-7db2-5ff8-703ce5c07066', 'maire-plateau', 'Promenade lagunaire démolie : comment sortir du conflit avec le District ?

Dans la nuit du 11 au 12 septembre 2026, des aménagements municipaux de la promenade lagunaire (projet Smart Plateau, dont Oxy Park II) ont été démolis entre les ponts FHB et Général-de-Gaulle. La mairie dit ne pas avoir été consultée. Quelle suite pour ces aménagements ?

AIP, 15 septembre 2026 : https://www.aip.ci/cote-divoire-aip-le-district-dabidjan-et-la-mairie-du-plateau-sopposent-sur-la-demolition-damenagements-de-la-promenade-lagunaire/
#Interpellation #Plateau', 16),
('454e83be-bdb4-c1a0-9e7d-2cda4cc5a3e1', 'maire-plateau', '2 600 arbres seulement : comment rafraîchir le Plateau ?

Le Plateau ne compte qu''environ 2 600 arbres ; les secteurs très bétonnés subissent des îlots de chaleur. La mairie veut planter 10 000 arbres d''ici 2028. Où, et à quel rythme ?

AIP, 22 mai 2026 : https://www.aip.ci/cote-divoire-aip-la-biodiversite-a-lepreuve-de-la-modernisation-urbaine-le-plateau-cherche-lequilibre-vert-reportage/
#Interpellation #Plateau', 15),
('a705d792-9cfc-ddea-725f-6b6d37727a9f', 'maire-port-bouet', 'Inondations : quels secteurs protéger en priorité ?

Port-Bouët figure parmi les zones touchées par les pluies diluviennes de juin 2024, et l''ONPC a inspecté ses sites à risque le 18 juillet 2024. Quels aménagements sont prévus pour les quartiers exposés ?

Office national de la protection civile, 18 juillet 2024 : https://www.onpc-ci.org/actualite/les-sites-a-risque-dinondation-de-port-bouet-et-de-songon-inspectes
#Interpellation #PortBouët #Inondations', 14),
('21c934ce-46ad-d76c-9f02-4c367c0ebb45', 'maire-port-bouet', 'La Promenade de Port-Bouët à l''abandon : quel rôle pour la commune ?

En janvier 2026, la Promenade était très dégradée : installations détériorées, herbes, éclairage défaillant, ordures. Le District en a annoncé la réhabilitation. Comment la commune en assurera-t-elle l''entretien ensuite ?

Presse Côte d''Ivoire, 19 janvier 2026 : https://pressecotedivoire.fr/24103-promenade-de-port-bouet-un-projet-de-plusieurs-milliards-laisse-a-labandon-que-bacongo-veut-rehabiliter
#Interpellation #PortBouët', 13),
('2a0e4c45-a819-7a19-fd38-109cb65ae13a', 'maire-treichville', 'Avaloirs bouchés, rue des Brasseurs, Belleville : quand finiront les montées d''eau ?

L''ONPC a identifié plusieurs sites à risque à Treichville (Restaurant Aboussouan, rue des Brasseurs, avenue 21 rue 7, Belleville, derrière le Lycée moderne) : avaloirs bouchés et conduits trop étroits, montées d''eau fréquentes qui rendent la circulation difficile. Quel programme de curage et d''élargissement ?

Office national de la protection civile, 28 mai 2025 : https://www.onpc-ci.org/actualite/lutte-contre-les-inondations-a-treichville-lonpc-poursuit-ses-visites
#Interpellation #Treichville #Inondations', 12),
('a9633ade-2880-e303-d58a-723c2c38f7c5', 'maire-yopougon', 'Sainte Rita, Lubafrik, Abobodoumé : quand les routes seront-elles réparées ?

Les pluies ont aggravé l''état de plusieurs voies (nids-de-poule, eau stagnante, axes impraticables). À Abobodoumé, la route vers Koweït a été coupée par les eaux usées et les bus n''atteignaient plus la gare depuis près de cinq mois. Quel calendrier de réfection ?

Presse Côte d''Ivoire, 20 avril 2024 : https://www.pressecotedivoire.fr/19647-yopougon-la-pluie-aggrave-letat-des-routes-provoquant-des-coupures-et-des-embouteillages
#Interpellation #Yopougon', 11),
('44540b43-9159-1f24-7d1d-bce52bb36c48', 'maire-bingerville', 'Après les inondations meurtrières de mai 2026, quelles protections pour les habitants ?

Les pluies exceptionnelles de fin mai 2026 ont causé des pertes en vies humaines et d''importants dégâts à Bingerville. Le Gouvernement a annoncé des travaux pour mieux canaliser les eaux, avec une solution complète sur plusieurs années. Quel rôle pour la commune d''ici là ?

Gouvernement de Côte d''Ivoire, 4 juin 2026 : https://www.gouv.ci/actualite/inondations-a-bingerville-le-gouvernement-annonce-dimportants-travaux-pour-trouver-une-solution-definitive-a-la-situation-4282
#Interpellation #Bingerville #Inondations', 10),
('7ae4da25-7cfe-3b2f-fef3-b0404257dcce', 'maire-songon', 'Classes surchargées : combien d''écoles manquent encore à Songon ?

La croissance de la population scolaire a obligé à agrandir l''EPP d''Abadjin Doumé pour réduire le nombre d''élèves par classe. Quel est le besoin restant dans la commune ?

AIP, 5 novembre 2025 : https://www.aip.ci/cote-divoire-aip-songon-trois-nouvelles-salles-de-classe-construites-a-lepp-abadjin-doume-pour-renforcer-la-capacite-daccueil/
#Interpellation #Songon', 9),
('7ad9f09b-62ef-ff16-f803-fe06e1473f58', 'maire-anyama', 'De 300 000 à 450 000 habitants en trois ans : comment suivre ?

Selon la maire, l''arrivée de familles déguerpies d''autres communes d''Abidjan a fait passer la population d''environ 300 000 à plus de 450 000 habitants en trois ans. Anyama ne compte que deux lycées publics. Quel plan pour les écoles, la santé et le logement ?

RFI, 23 octobre 2025 : https://www.rfi.fr/fr/afrique/20251023-comment-la-commune-d-anyama-illustre-le-d%C3%A9veloppement-contrast%C3%A9-de-la-c%C3%B4te-d-ivoire
#Interpellation #Anyama', 8),
('06a301ed-e9f4-e133-735a-4fc9ede826c1', 'maire-korhogo', '4,41 % des recettes 2026 collectées fin mars : comment financer les projets ?

Au 31 mars 2026, Korhogo avait recouvré 185,9 millions de FCFA sur un budget de 4,208 milliards (4,41 %). En 2025, 40,40 % seulement des dépenses prévues ont été exécutées, laissant un excédent de plus de 3 milliards lié en partie à des investissements non réalisés. Comment accélérer l''exécution ?

AIP, 27 avril 2026 : https://www.aip.ci/cote-divoire-aip-korhogo-35-projets-acheves-et-17-en-cours-presentes-pendant-la-session-du-conseil-municipal/
#Interpellation #Korhogo', 7),
('e894d7d9-cb89-d971-df90-b0fe270f85c3', 'maire-yamoussoukro', 'Dix marchés annoncés : où, quand et avec quel budget ?

Le conseil municipal d''août 2026 envisage dix nouveaux marchés de proximité, mais ni les sites, ni le budget, ni le calendrier n''ont été rendus publics, et les projets BOT de N''Zuessy et Kokrénou ont été annulés. Les commerçants attendent des précisions.

Koaci, 3 septembre 2026 : https://www.koaci.com/article/2026/09/03/cote-divoire/politique/cote-divoire-yamoussoukro-10-nouveaux-marches-de-proximite-annonces-pour-accelerer-le-developpement-local_200140.html
#Interpellation #Yamoussoukro', 6),
('69d7955b-2a92-bd7b-14d5-0ccab49de0d6', 'maire-man', 'Relier les quartiers de Man : quels ouvrages de franchissement, et quand ?

Le conseil municipal du 3 juillet 2025 a annoncé des ouvrages de franchissement entre quartiers et un programme de reprofilage des voies pour faciliter la mobilité, sans calendrier ni coût publiés. Quels quartiers seront desservis en premier ?

AIP, 6 juillet 2025 : https://www.aip.ci/cote-divoire-aip-man-le-conseil-municipal-annonce-des-chantiers-structurants-pour-les-six-prochains-mois/
#Interpellation #Man', 5),
('3553584d-e4a8-612c-9d76-21d8af1d8cfa', 'maire-gagnoa', 'Grand marché : un an perdu faute de dossier transmis. Quelles garanties ?

Le contrat du grand marché, approuvé en conseil le 11 mars 2025, a dû être revoté le 24 février 2026 : la mairie n''avait pas transmis à temps les pièces à la Direction générale de la décentralisation. Comment éviter de nouveaux retards ?

Koaci, 26 février 2026 : https://www.koaci.com/article/2026/02/26/cote-divoire/societe/cote-divoire-gagnoa-les-grands-projets-de-developpement-pour-2026-valides-par-le-conseil-municipal_194696.html
#Interpellation #Gagnoa', 4),
('79a13571-1bb8-e530-0320-5e75feeddcce', 'maire-abengourou', 'Caniveaux et routes en retard : quand la voirie sera-t-elle livrée ?

Au conseil municipal du 31 octobre 2025, le maire a indiqué qu''environ 82 % des actions prévues en 2025 étaient réalisées, mais que « le gros des sujets qui restent en suspense, c''est la voirie » : le projet de caniveaux et de routes a pris du retard. Quelle nouvelle échéance ?

AllAfrica, 3 novembre 2025 : https://fr.allafrica.com/stories/202511030472.html
#Interpellation #Abengourou', 3),
('06c3e65f-ea96-4c00-62ce-6f83c247810e', 'maire-boundiali', 'Un excédent d''environ un milliard de FCFA : pour quels projets ?

Le compte administratif présenté au conseil municipal du 2 mai 2026 fait apparaître un excédent budgétaire d''environ un milliard de FCFA. Les habitants aimeraient savoir quels projets il financera, et quand.

Fraternité Matin, via AllAfrica, 3 mai 2026 : https://fr.allafrica.com/stories/202605040419.html
#Interpellation #Boundiali', 2),
('4662b95f-a87f-49e4-0d7f-e60f4dedf5e2', 'conseil-regional-poro', '36,64 % des recettes 2025 recouvrées fin septembre : comment tenir le budget 2026 ?

Au 30 septembre 2025, la région du Poro avait mobilisé 1,99 milliard de FCFA, soit un taux de recouvrement cumulé de 36,64 %. Le budget 2026 adopté en novembre 2025 grimpe pourtant de 34,28 %, à 7,33 milliards. Comment les recettes suivront-elles ?

AIP, 23 novembre 2025 : https://www.aip.ci/cote-divoire-aip-le-budget-primitif-2026-de-la-region-du-poro-en-hausse-de-3428/
#Interpellation #Poro #Korhogo', 1)
) v(post, office, text, n)
join officials o on o.office_key = v.office
cross join (select id from profiles where handle = 'politique') ed
on conflict (id) do nothing;

