('053801e4-5fe2-6cac-b110-d3bf12cab3bb', 'maire-abobo', 'Bitumer la voie Pharmacie Saint-Antoine de Sagbé – Collège Bocabo', 'Voie longtemps réclamée par les habitants de Sagbé et de Bocabo. Coût annoncé d''environ 2 milliards de FCFA, entièrement financé par la mairie ; chantier prévu sur neuf mois.', 'https://www.fratmat.info/article/2637792/economie/abobo-kandia-camara-lance-les-travaux-de-bitumage-de-la-voie-reliant-la-pharmacie-saint-antoine-de-sagbe-au-college-bocabo', '2025-10-24', '2026-07-01', 'en_cours', null),
('1f904868-8e93-f52a-f41c-01e897d10438', 'maire-abobo', '5 000 logements sociaux, économiques et de standing en cinq ans', 'Convention signée par la maire avec Sablux Côte d''Ivoire : 1 000 logements livrables par an à partir de 2026, en location-vente sur 25 ans, attribués selon des critères sociaux validés en conseil municipal.', 'https://www.fratmat.info/article/2639616/economie/construction-5000-logements-sociaux-economiques-sortiront-de-terre-a-abobo-dici-5-ans', '2026-01-27', '2031-01-01', 'annoncee', null),
('eef22b66-2ba5-9fb3-ad16-a6dc2f9ad50d', 'maire-adjame', 'Un marché Gouro ultra-moderne à Adjamé-Roxy', 'Grands travaux lancés après le déplacement du réseau de la SODECI ; les commerçantes devaient disposer de l''équipement d''ici décembre 2024.', 'https://news.abidjan.net/articles/716747/construction-du-marche-gouro-ultra-moderne-a-adjame-roxy-debut-des-grands-travaux-apres-le-deplacement-du-reseau-sodeci', null, '2024-12-01', 'en_cours', null),
('4d133867-839f-c90f-8a20-1b951e1f2718', 'maire-adjame', 'Réhabiliter et réaménager la cour de la mairie', 'Travaux de réaménagement portés par le député-maire, avec l''appui technique et logistique du District autonome d''Abidjan.', 'https://connectionivoirienne.net/2025/05/26/adjame-la-cour-de-la-mairie-en-pleine-rehabilitation/', '2025-05-26', null, 'en_cours', null),
('186d3458-57f7-9b2f-a96a-d2d1c155944c', 'maire-attecoube', 'Valoriser les déchets plastiques (projet pilote d''économie circulaire)', 'Projet lancé par le maire avec ONU-Habitat et l''ONG AVSI : restructuration de l''unité de valorisation des déchets plastiques, formation et sensibilisation, au bénéfice notamment des jeunes, des femmes et des migrants vulnérables. Durée annoncée : février à novembre 2025.', 'https://mairieattecoube.ci/actualite_details/54', '2025-02-01', '2025-11-01', 'en_cours', null),
('da3e3832-e6ae-b59d-c499-3d34f7e37643', 'maire-attecoube', 'Construire les marchés de Locodjro Santé et d''Abobo-Doumé', 'Projet examiné par le conseil municipal lors de sa première session ordinaire de 2024.', 'http://mairieattecoube.ci/test/actualite_details/18', '2024-05-07', null, 'annoncee', null),
('168b27f2-7c75-9ba2-de40-a93d31451900', 'maire-cocody', 'Plan quinquennal d''insertion professionnelle des jeunes', 'Lancé avec le premier Salon des métiers (16 et 17 août 2024, à la mairie) avec Alliance for Youth et l''UNESCO : emploi, formation et réseautage pour les 18-35 ans.', 'https://www.fratmat.info/article/419502/societe/cocody-jean-marc-yace-lance-un-plan-dinsertion-professionnelle-pour-la-jeunesse', '2024-08-20', '2029-01-01', 'en_cours', null),
('25dabbcd-d644-443b-e958-c61b530b35db', 'maire-koumassi', 'Programme triennal 2025-2027 : 41 opérations', 'Adopté à l''unanimité le 3 septembre 2024 : électrification des voies, réhabilitation d''écoles, assainissement et drainage, équipement des centres de santé, acquisition d''engins de travaux publics.', 'https://www.fratmat.info/article/693413/regions/koumassi/mairie-de-koumassi-le-programme-triennal-2025-2027-adopte', '2024-09-03', '2027-12-01', 'en_cours', null),
('62d91d22-735f-cdfb-e8ef-d5e141e515ba', 'maire-marcory', 'Organiser les États généraux de la qualité et de la salubrité', 'Annoncés par le maire pour renforcer la proximité avec les habitants, distinguer les quartiers propres et améliorer durablement le cadre de vie.', 'https://cinews.ci/marcory-le-maire-raoul-aby-annonce-lorganisation-des-etats-generaux-de-la-qualite-et-de-la-salubrite/', '2026-02-14', null, 'annoncee', null),
('24b99837-61e8-c196-2d1f-75cbbbb858a7', 'maire-marcory', '100 millions de FCFA de prise en charge scolaire chaque année', 'Aides remises à des élèves et étudiants de 134 établissements ; le maire a indiqué que cette aide est prévue chaque année.', 'https://www.fratmat.info/article/2401246/societe/marcory-la-maire-offre-100-millions-de-f-cfa-de-prise-en-charge-scolaire', '2024-12-11', null, 'en_cours', null),
('7db0bd03-4c7f-5a88-4afa-513b229dc304', 'maire-plateau', 'Éclairage public intelligent et télégéré (Smart Plateau)', 'Premier éclairage public ajustable et télégéré point par point du pays, issu de la convention signée avec ECLATEC le 25 janvier 2023 ; contribution de la mairie d''environ 100 millions de FCFA. Remise officielle le 24 février 2026.', 'https://www.aip.ci/electionpresidentielle2025/article.php?id=324721', '2023-01-25', null, 'tenue', null),
('5367fe23-8b56-086f-94ed-aa1967856147', 'maire-plateau', 'Planter 10 000 arbres d''ici 2028', 'Programme de reboisement commencé en 2025 : îlots de fraîcheur et corridors écologiques.', 'https://www.aip.ci/cote-divoire-aip-la-biodiversite-a-lepreuve-de-la-modernisation-urbaine-le-plateau-cherche-lequilibre-vert-reportage/', '2025-01-01', '2028-12-01', 'en_cours', null),
('4ff1cd05-b371-c7c6-4e16-ccee89eff354', 'maire-plateau', 'Installer des parcmètres pour organiser le stationnement', 'Lancement annoncé par le maire au conseil municipal du 16 avril 2024.', 'https://www.fratmat.info/article/239221/politique/affaire-suppression-de-la-commune-du-plateau-le-communique-du-conseil-municipal-qui-eclaire-sur-la-situation', '2024-04-16', null, 'annoncee', null),
('b51d1ceb-b456-a081-eff3-21684dacb294', 'maire-yopougon', '120 logements gratuits et des équipements sociaux à Andokoi', 'Première pierre posée par le maire d''un ensemble de 120 logements pour des familles démunies, avec une école primaire de six classes, un centre de santé, un forage et une mosquée. Réalisation annoncée en six mois.', 'https://www.aip.ci/cote-divoire-aip-adama-bictogo-pose-la-premiere-pierre-dun-quartier-residentiel-et-dinfrastructures-sociales-a-yopougon/', '2025-05-07', '2025-11-01', 'annoncee', null),
('73a41b39-acfa-c8c4-151c-d3ac85b9c690', 'maire-yopougon', 'Réaménager les ronds-points et les trois entrées de la commune', 'Projets validés par le conseil municipal : sécurité, espaces pour les familles et les enfants, sport, salubrité, restauration.', 'https://www.koaci.com/article/2026/05/13/cote-divoire/societe/cote-divoire-yopougon-des-travaux-de-rehabilitation-damenagement-et-dembellissement-annonces-dans-la-commune_196625.html', '2026-05-13', null, 'annoncee', null),
('5809e4d4-40c2-afa4-37fe-b32349460170', 'maire-bingerville', 'Budget 2026 : 2,17 milliards de FCFA pour l''investissement', 'Le budget primitif 2026, adopté à l''unanimité, réserve 2 168 334 000 FCFA à l''investissement, soit 53,59 % du budget communal.', 'https://www.aip.ci/cote-divoire-aip-le-budget-primitif-2026-de-la-commune-de-bingerville-arrete-a-plus-de-4-milliards-fcfa/', '2026-01-28', null, 'annoncee', null),
('a334e28e-f4c9-5dc2-4343-32ecd461f0e0', 'maire-songon', 'Trois salles de classe à l''EPP Abadjin Doumé', 'Bâtiment de trois salles pour 32 millions de FCFA, réalisé à près de 90 % lors de la visite du député-maire le 3 novembre 2025 ; une clôture est annoncée ensuite.', 'https://www.aip.ci/cote-divoire-aip-songon-trois-nouvelles-salles-de-classe-construites-a-lepp-abadjin-doume-pour-renforcer-la-capacite-daccueil/', '2025-11-05', null, 'en_cours', null),
('ab3623e5-c308-b765-f938-5aeb69c9fd09', 'maire-songon', 'Deux écoles primaires publiques à Songon Adiopoto', 'Construction entreprise par le conseil municipal pour rapprocher l''école des familles.', 'https://www.aip.ci/cote-divoire-aip-deux-ecoles-primaires-en-construction-a-songon-adiopoto-pour-rapprocher-lenseignement-des-familles/', '2025-11-12', null, 'en_cours', null),
('d3972061-2218-4bf3-dc6d-c8ea2afa602d', 'maire-songon', 'Feux tricolores aux carrefours de Songon', 'Installés puis rendus opérationnels pour la sécurité routière, après une attente de longue date des habitants.', 'https://www.aip.ci/cote-divoire-aip-des-feux-tricolores-desormais-operationnel-a-songon-pour-renforcer-la-securite-routiere/', '2025-09-03', null, 'tenue', null),
('2eb72d13-833b-09f1-1230-bd1a783217a1', 'maire-anyama', 'Étendre le réseau d''eau potable', 'Travaux démarrés en juillet 2024 pour une durée annoncée de 18 mois ; la maire présente l''eau comme un problème important de la commune.', 'https://www.aip.ci/cote-divoire-aip-le-maire-annonce-le-demarrage-des-travaux-dextension-de-leau-potable-et-leffectivite-du-projet-de-labattoir-moderne/', '2024-07-01', '2026-01-01', 'en_cours', null),
('d8f80ca6-2f83-07ef-1a89-2f68fd247ed5', 'maire-anyama', 'Un abattoir moderne sur 228 hectares', 'Projet attendu depuis des décennies : financement global annoncé de 30 milliards de FCFA ; première phase de 50 hectares pour le parc à bétail.', 'https://www.aip.ci/cote-divoire-aip-le-maire-annonce-le-demarrage-des-travaux-dextension-de-leau-potable-et-leffectivite-du-projet-de-labattoir-moderne/', '2024-07-21', null, 'annoncee', null),
('95ea9f1f-726a-6897-ccbc-35053f9b9fb8', 'maire-korhogo', 'Programme d''investissement : 77 projets', 'Bilan présenté au conseil municipal du 25 avril 2026 : 35 projets achevés, 17 en cours d''exécution ; la plupart des autres, prévus pour 2026, sont en passation des marchés.', 'https://www.aip.ci/cote-divoire-aip-korhogo-35-projets-acheves-et-17-en-cours-presentes-pendant-la-session-du-conseil-municipal/', '2026-04-25', null, 'partiellement_tenue', null),
('9a1b8d9c-5025-b653-380f-ddff7aa8a250', 'maire-korhogo', 'Des mairies annexes dans les quartiers pour rapprocher l''état civil', 'Travaux lancés les 18 et 19 juillet 2025 pour deux mairies annexes (quartiers Cocody et Marcory) et une aire de jeux à Mongaha. Le maire a annoncé d''autres annexes à Waraniéné, Natio, Kassirimé et Aoussabougou.', 'https://www.aip.ci/cote-divoire-aip-le-maire-de-korhogo-lance-les-travaux-de-construction-de-deux-mairies-annexes/', '2025-07-20', null, 'en_cours', null),
('56a065c4-39ec-9caf-08e9-992927a47ec7', 'maire-korhogo', 'Centre de santé intégré de Dokaha', 'Infirmerie et maternité inaugurées le 29 novembre 2025, entièrement financées par la mairie sur le budget d''investissement 2024 : 40,93 millions de FCFA de construction et 28 millions d''équipements.', 'https://www.aip.ci/cote-divoire-aip-le-maire-de-korhogo-dote-le-village-de-dokaha-dun-centre-de-sante-integre/', '2024-01-01', null, 'tenue', null),
('bbbcfdc3-66f2-befe-e380-203d992d96fa', 'maire-yamoussoukro', 'Construire dix nouveaux marchés de proximité', 'Annoncé au conseil municipal d''août 2026 (onze points adoptés à l''unanimité), avec une plateforme de collecte des taxes municipales et la formation de 60 jeunes en maçonnerie, plomberie et électricité. Les projets BOT de N''Zuessy et Kokrénou sont annulés.', 'https://www.koaci.com/article/2026/09/03/cote-divoire/politique/cote-divoire-yamoussoukro-10-nouveaux-marches-de-proximite-annonces-pour-accelerer-le-developpement-local_200140.html', '2026-08-01', null, 'annoncee', null),
('1b998513-caf7-fae7-15fd-626b511271b1', 'maire-man', 'Un palais de la culture de 3 000 places', 'Annoncé au conseil municipal du 3 juillet 2025 parmi les chantiers des six mois suivants : salle de spectacle et cinéma, « un espace convivial qui fait défaut » selon le maire.', 'https://www.aip.ci/cote-divoire-aip-man-le-conseil-municipal-annonce-des-chantiers-structurants-pour-les-six-prochains-mois/', '2025-07-03', null, 'annoncee', null),
('419d5604-5030-a546-9be4-b28a089daadb', 'maire-man', 'Un fonds de 100 millions de FCFA pour l''emploi des jeunes', 'Annoncé au conseil municipal du 3 juillet 2025, avec la formation de 50 jeunes enseignants recrutés ensuite par les écoles privées partenaires et des formations numériques gratuites à la bibliothèque municipale.', 'https://www.aip.ci/cote-divoire-aip-man-le-conseil-municipal-annonce-des-chantiers-structurants-pour-les-six-prochains-mois/', '2025-07-03', null, 'annoncee', null),
('af7df1b5-9417-570b-be0e-fc1dcb8732a5', 'maire-gagnoa', 'Construire le grand marché couvert de Gagnoa', 'Premier grand projet annoncé par le maire à sa réélection. Le 24 février 2026, le conseil municipal a voté à l''unanimité les plans, les devis et la signature d''un contrat BOT avec LAH Properties et Natha SARL.

Autre source :
Koaci, 16 octobre 2023 : https://www.koaci.com/article/2023/10/16/cote-divoire/politique/cote-divoire-reelu-maire-de-gagnoa-yssouf-diabate-mon-premier-grand-projet-est-la-construction-du-grand-marche_173020.html', 'https://www.koaci.com/article/2026/02/26/cote-divoire/societe/cote-divoire-gagnoa-les-grands-projets-de-developpement-pour-2026-valides-par-le-conseil-municipal_194696.html', '2023-10-01', null, 'annoncee', null),
('2c0a699b-2881-c91e-7892-e00e3aba755f', 'maire-abengourou', 'Programme d''investissement 2025 : écoles de proximité, centres de santé, voirie', 'Environ 82 % des actions prévues réalisées au 31 octobre 2025 selon le maire ; réhabilitation de la voirie attendue avant la fin de l''année.', 'https://fr.allafrica.com/stories/202511030472.html', '2025-11-03', null, 'partiellement_tenue', null),
('feb37ccc-6dbd-04fe-2ad7-4d07135ee54d', 'maire-adzope', 'Budget 2026 de 2,42 milliards de FCFA', 'Le conseil municipal a adopté le 27 novembre 2025 un budget primitif 2026 arrêté à 2 422 705 000 FCFA, contre 1 860 800 000 FCFA en 2025.', 'https://www.aip.ci/cote-divoire-aip-le-budget-primitif-2026-mairie-dadzope-en-hausse-de-3399-par-rapport-a-lannee-precedente/', '2025-11-27', null, 'annoncee', null),
('1f9784a1-0019-13b5-9cfd-dfdf4ef85ca1', 'maire-agnibilekrou', 'Moderniser le marché, réhabiliter l''abattoir, bâtir un centre commercial', 'Annoncés par le maire au conseil municipal du 2 mai 2026 : modernisation du marché municipal, réhabilitation de l''abattoir, logements et bureaux du préfet et du sous-préfet, centre commercial sur trois niveaux. Financement en BOT par des consortiums brésiliens, pour une concession de 25 à 30 ans ; contrats encore à signer.', 'https://www.aip.ci/cote-divoire-aip-agnibilekrou-le-maire-siandou-fofana-annonce-de-grands-projets-urbains-structurants/', '2026-05-02', null, 'annoncee', null),
('cb1916d1-0330-230c-d128-e4c9b918a2ad', 'conseil-regional-san-pedro', 'Programme triennal 2027-2029 : 15,06 milliards de FCFA', 'Adopté en session ordinaire le 20 août 2026 : 27 actions et 134 opérations (dont 41 nouvelles) dans l''éducation, la santé, l''eau potable et la réhabilitation des pistes rurales ; 236 millions de FCFA d''actions financées sur ressources propres (associations, éducation, femmes et jeunes).', 'https://www.aip.ci/cote-divoire-aip-san-pedro-plus-de-15-milliards-fcfa-programmes-pour-accelerer-le-developpement-local-sur-trois-ans/', '2026-08-20', '2029-12-01', 'annoncee', null),
('c11b7525-9587-19fe-2b20-fa12fa5b7adf', 'conseil-regional-la-me', 'Budget 2026 : 5,08 milliards de FCFA pour 89 opérations de terrain', 'Budget primitif 2026 de 6 425 299 000 FCFA adopté le 14 novembre 2025 à Yakassé-Attobrou, en hausse de 29 %. L''investissement (79 %) couvre 25 actions et 89 opérations : éducation, santé, insertion des jeunes, autonomisation des femmes, environnement.', 'https://www.aip.ci/cote-divoire-aip-le-budget-primitif-de-lexercice-2026-du-conseil-regional-de-la-me-adopte-a-plus-de-six-milliards-de-francs-cfa/', '2025-11-14', null, 'annoncee', null),
('da6a71d2-55b9-5f99-7398-95652023e6f9', 'conseil-regional-belier', 'Budget 2027 de 8,68 milliards de FCFA', 'Adopté à l''unanimité le 9 octobre 2026 à Molonou (Tiébissou), en hausse de 1,744 milliard de FCFA par rapport à 2026 (6,937 milliards).', 'https://www.aip.ci/cote-divoire-aip-le-conseil-regional-du-belier-adopte-un-budget-primitif-2027-de-8681-milliards-fcfa-en-hausse-de-1744-milliard-fcfa/', '2026-10-09', null, 'annoncee', null),
('305f3235-cb1e-7d06-e161-150ef26e14c0', 'conseil-regional-indenie-djuablin', 'Livrer 2 500 tables-bancs aux collèges de proximité', 'Quatre collèges de proximité ont ouvert pour l''année 2025-2026 ; 2 500 tables-bancs ont été annoncées pour ces établissements, livraison en attente au 6 octobre 2025. Le budget 2026 adopté ce jour-là atteint 6,64 milliards de FCFA, dont 5,30 milliards d''investissement.', 'https://fr.allafrica.com/stories/202510100538.html', '2025-10-06', null, 'en_cours', null),
('a42254e1-5c68-7d95-ab18-d06332a10cc9', 'conseil-regional-poro', '600 millions de FCFA pour les cantines scolaires en 2026', 'Inscrits au budget primitif 2026 de la région du Poro (7,33 milliards de FCFA, +34,28 %), adopté le 22 novembre 2025 à Korhogo.', 'https://www.aip.ci/cote-divoire-aip-le-budget-primitif-2026-de-la-region-du-poro-en-hausse-de-3428/', '2025-11-22', null, 'annoncee', null),
('c82bc6f3-ffcc-2aa8-7cac-5193a11da80b', 'conseil-regional-agneby-tiassa', 'Programme triennal 2027-2029 : 11,56 milliards de FCFA, dont 4,15 pour l''éducation', 'Adopté à l''unanimité le 5 juin 2026 : 107 opérations (83 reconduites, 24 nouvelles) ; éducation 4,15 milliards, routes 1,1 milliard, eau 630 millions, sécurité 487 millions. Le siège du conseil régional (822 millions) est en construction.', 'https://www.aip.ci/cote-divoire-aip-lagneby-tiassa-adopte-son-programme-triennal-2027-2029-de-plus-de-115-milliards-fcfa/', '2026-06-05', '2029-12-01', 'en_cours', null),
('70f05593-d57d-48bd-6822-8267c16019ff', 'conseil-regional-cavally', 'Programme triennal 2026-2028 : 11,42 milliards de FCFA', 'Adopté le 18 avril 2025 à Guiglo : éducation 4,30 milliards, santé 1,14 milliard, routes 1,09 milliard, électrification 644 millions, eau 611 millions, et 900 millions d''appui direct aux populations. 7,35 milliards sont programmés dès 2026.', 'https://www.aip.ci/cote-divoire-aip-2eme-session-2025-le-conseil-regional-du-cavally-adopte-son-programme-triennal-2026-2028/', '2025-04-18', '2028-12-01', 'en_cours', null)
) v(id, office, title, description, source_url, made_at, due_at, status, status_note)
join officials o on o.office_key = v.office
cross join (select id from profiles where handle = 'politique') ed
on conflict (id) do nothing;
